#![allow(dead_code)]
//! Rust port of engine_v2.popcore.count_batch (engine_v2/popcore.py), generated by fast-anything.
//! Includes place_stars (engine_v2/chart.py), sanfang and the per-rule counting, so Rust is entered once per batch.

use pyo3::exceptions::{PyIndexError, PyKeyError, PyValueError};
use pyo3::prelude::*;
use std::collections::HashMap;

const BR: [&str; 12] = ["子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥"];
const BRC: &str = "子丑寅卯辰巳午未申酉戌亥";
const STEM: [&str; 10] = ["甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸"];
const STEMC: &str = "甲乙丙丁戊己庚辛壬癸";
const NAYIN: &str = "金金火火木木土土金金火火水水土土金金木木水水土土火火木木水水金金火火木木土土金金火火水水土土金金木木水水土土火火木木水水";
const LU: &str = "寅卯巳午巳午申酉亥子";
const JIEKONG: [&str; 10] = ["申酉", "午未", "辰巳", "寅卯", "子丑", "申酉", "午未", "辰巳", "寅卯", "子丑"];
const TIGER: [usize; 10] = [2, 4, 6, 8, 0, 2, 4, 6, 8, 0]; // 五虎遁, as STEM index

fn bi_c(c: char) -> PyResult<i64> {
    BRC.chars().position(|x| x == c).map(|p| p as i64).ok_or_else(|| PyValueError::new_err("substring not found"))
}

fn one_char(s: &str) -> Option<char> {
    let mut it = s.chars();
    let c = it.next()?;
    if it.next().is_some() { None } else { Some(c) }
}

fn stem_idx(s: &str) -> PyResult<usize> {
    one_char(s).and_then(|c| STEMC.chars().position(|x| x == c)).ok_or_else(|| PyKeyError::new_err(s.to_string()))
}

/// Python-style str indexing (negative allowed) of a char string.
fn pyidx(s: &str, i: i64) -> PyResult<char> {
    let n = s.chars().count() as i64;
    let j = if i < 0 { i + n } else { i };
    if j < 0 || j >= n {
        return Err(PyIndexError::new_err("string index out of range"));
    }
    Ok(s.chars().nth(j as usize).unwrap())
}

fn bi_at(s: &str, i: i64) -> PyResult<i64> {
    bi_c(pyidx(s, i)?)
}

fn bz(v: i64) -> &'static str {
    BR[v.rem_euclid(12) as usize]
}

fn mk_ma(yb: char) -> PyResult<char> {
    Ok(match yb { '寅' | '午' | '戌' => '申', '申' | '子' | '辰' => '寅', '巳' | '酉' | '丑' => '亥', '亥' | '卯' | '未' => '巳', _ => return Err(PyKeyError::new_err(yb.to_string())) })
}
fn mk_hl(yb: char) -> PyResult<(char, char)> {
    Ok(match yb {
        '寅' | '午' | '戌' => ('丑', '卯'), '申' | '子' | '辰' => ('寅', '戌'),
        '巳' | '酉' | '丑' => ('卯', '戌'), '亥' | '卯' | '未' => ('酉', '戌'),
        _ => return Err(PyKeyError::new_err(yb.to_string())) })
}
/// SAN group index: 0 寅午戌, 1 申子辰, 2 巳酉丑, 3 亥卯未
fn mk_san(yb: char) -> PyResult<usize> {
    Ok(match yb { '寅' | '午' | '戌' => 0, '申' | '子' | '辰' => 1, '巳' | '酉' | '丑' => 2, '亥' | '卯' | '未' => 3, _ => return Err(PyKeyError::new_err(yb.to_string())) })
}
fn kui(si: usize) -> (char, char) {
    match si { 0 | 4 | 6 => ('丑', '未'), 1 | 5 => ('子', '申'), 2 | 3 => ('亥', '酉'), 7 => ('午', '寅'), _ => ('卯', '巳') }
}

struct Kong {
    xun: [i64; 2],
    jie: [i64; 2],
    zj: i64,
    zx: i64,
    zheng: Vec<i64>,
    pang: Vec<i64>,
}

fn kong(si: usize, yb: i64) -> PyResult<Kong> {
    let k = (0..60usize).find(|i| i % 10 == si && (*i % 12) as i64 == yb)
        .ok_or_else(|| PyValueError::new_err("StopIteration"))?;
    let x0 = k - k % 10;
    let xun = [((x0 + 10) % 12) as i64, ((x0 + 11) % 12) as i64];
    let jc: Vec<char> = JIEKONG[si].chars().collect();
    let jie = [bi_c(jc[0])?, bi_c(jc[1])?];
    let yang = si % 2 == 0;
    let pick = |pair: &[i64; 2]| -> PyResult<i64> {
        pair.iter().copied().find(|z| (z % 2 == 0) == yang).ok_or_else(|| PyIndexError::new_err("list index out of range"))
    };
    let zj = pick(&jie)?;
    let zx = pick(&xun)?;
    let mut zheng = vec![zj];
    if zx != zj { zheng.push(zx); }
    zheng.sort();
    let mut pang: Vec<i64> = Vec::new();
    for v in xun.iter().chain(jie.iter()) {
        if !zheng.contains(v) && !pang.contains(v) { pang.push(*v); }
    }
    pang.sort();
    Ok(Kong { xun, jie, zj, zx, zheng, pang })
}


const POS_NAMES: [&str; NPOS] = ["자미", "천기", "태양", "무곡", "천동", "염정", "천부", "태음", "탐랑", "거문", "천상", "천량", "칠살", "파군", "좌보", "우필", "문창", "문곡", "천괴", "천월", "녹존", "경양", "타라", "천마", "화성", "영성", "지겁", "지공", "천형", "천요", "삼태", "팔좌", "홍란", "천희", "함지", "천덕", "용덕", "월덕", "년해", "대모", "겁살", "화개", "고진", "과숙", "파쇄", "용지", "봉각", "천곡", "천허", "천공", "천관", "천복", "천주", "홍염", "비렴", "천무", "천월(月)", "음살", "해신", "은광", "천귀", "태보", "봉고", "천재", "천수", "천상(傷)", "천사", "절공", "순공"];
const NPOS: usize = 69;
const MAIN14: [&str; 14] = ["자미", "천기", "태양", "무곡", "천동", "염정", "천부", "태음", "탐랑", "거문", "천상", "천량", "칠살", "파군"];

/// (pos values as raw ints, ming, shen); the last two entries are 절공, 순공.
fn stars(ys: &str, yb: &str, m: i64, d: i64, h: i64) -> PyResult<([i64; NPOS], i64, i64)> {
    let si = stem_idx(ys)?;
    let ybc = one_char(yb).ok_or_else(|| PyKeyError::new_err(yb.to_string()))?;
    let y = bi_c(ybc)?;
    let b = |c: char| -> i64 { BRC.chars().position(|x| x == c).unwrap() as i64 };
    let (yin, chen, xu, yo, chou, hai, wu, mao, wei) = (b('寅'), b('辰'), b('戌'), b('酉'), b('丑'), b('亥'), b('午'), b('卯'), b('未'));

    let ming = (yin + m - 1 - h).rem_euclid(12);
    let shen = (yin + m - 1 + h).rem_euclid(12);
    let tiger = TIGER[si];
    let stem_of = |k: i64| -> usize { (tiger + k as usize) % 10 };
    // stems[bz(ming)]: k such that (yin+k)%12 == ming
    let kming = (ming - yin).rem_euclid(12);
    let ming_stem = stem_of(kming);
    let k60 = (0..60usize).find(|i| i % 10 == ming_stem && (*i % 12) as i64 == ming)
        .ok_or_else(|| PyValueError::new_err("StopIteration"))?;
    let n: i64 = match NAYIN.chars().nth(k60).unwrap() { '水' => 2, '木' => 3, '金' => 4, '土' => 5, _ => 6 };
    let mut x = 0i64;
    while (d + x).rem_euclid(n) != 0 { x += 1; }
    let q = (d + x).div_euclid(n);
    let zw = (yin + q - 1 + if x % 2 != 0 { -x } else { x }).rem_euclid(12);
    let tf = (4 - zw).rem_euclid(12);

    let ma = b(mk_ma(ybc)?);
    let (hc, lc) = mk_hl(ybc)?;
    let san = mk_san(ybc)?;
    let lu = bi_c(LU.chars().nth(si).unwrap())?;
    let (k0, k1) = kui(si);
    let xian: [char; 4] = ['卯', '酉', '午', '子'];
    let jies: [char; 4] = ['亥', '巳', '寅', '申'];
    let huag: [char; 4] = ['戌', '辰', '丑', '未'];
    let sea: i64 = match ybc { '亥' | '子' | '丑' => 0, '寅' | '卯' | '辰' => 1, '巳' | '午' | '未' => 2, _ => 3 };
    let feilian = bi_c("申酉戌巳午未寅卯辰亥子丑".chars().nth(y as usize).unwrap())?;
    let wen_chang = xu - h;
    let wen_qu = chen + h;

    let kg = kong(si, y)?;

    let pos: [i64; NPOS] = [
        (zw), (zw - 1), (zw - 3), (zw - 4), (zw - 5), (zw - 8),
        (tf), (tf + 1), (tf + 2), (tf + 3), (tf + 4), (tf + 5), (tf + 6), (tf + 10),
        (chen + m - 1), (xu - (m - 1)), (wen_chang), (wen_qu),
        (b(k0)), (b(k1)), (lu), (lu + 1), (lu - 1),
        (ma), (b(hc) + h), (b(lc) + h), (hai + h), (hai - h),
        (yo + m - 1), (chou + m - 1),
        (chen + m - 1 + d - 1), (xu - (m - 1) - (d - 1)),
        (mao - y), (yo - y),
        (b(xian[san])),
        (yo + y), (wei + y), (b('巳') + y), (xu - y),
        (y + 6 + if y % 2 == 0 { 1 } else { -1 }),
        (b(jies[san])), (b(huag[san])),
        (bi_at("寅巳申亥", sea)?), (bi_at("戌丑辰未", sea)?),
        (bi_at("巳酉丑", ("子午卯酉寅申巳亥辰戌丑未".chars().position(|c| c == ybc).unwrap() / 4) as i64)?),
        (chen + y), (xu - y), (wu - y), (wu + y), (y + 1),
        (bi_at("未辰巳寅卯酉亥酉戌午", si as i64)?), (bi_at("酉申子亥卯寅午巳午巳", si as i64)?),
        (bi_at("巳午子巳午申寅午酉戌", si as i64)?), (bi_at("午申寅未辰辰戌酉子申", si as i64)?),
        (feilian),
        (bi_at("巳申寅亥", (m - 1).rem_euclid(4))?), (bi_at("戌巳辰寅未卯亥未寅午戌寅", m - 1)?),
        (bi_at("寅子戌申午辰", (m - 1).rem_euclid(6))?), (bi_at("申戌子寅辰午", (m - 1).div_euclid(2))?),
        (wen_chang + d - 2), (wen_qu + d - 2),
        (wu + h), (yin + h),
        (ming + y), (shen + y),
        (ming - 7), (ming - 5),
        (kg.zj), (kg.zx),
    ];

    Ok((pos, ming, shen))
}

enum Tok {
    ShenMing,
    Ming,
    NoMain,
    Gung(u16),
    Gan(u16),
    Hua(Option<u8>),
    Dong(u128, bool, bool), // mask of present-able names, all-required, some name unresolvable
    Hoe(u128, bool, bool),
}

enum Br { None, MiaoWang, Xian, Ping, NotMiaoWang, Bad(String) }

struct Rule {
    idx: i64,
    star: Option<usize>,
    br: Br,
    is_hung: bool,
    hung_only: bool,
    toks: Vec<Tok>,
}

fn key_err<T>(s: &str) -> PyResult<T> {
    Err(PyKeyError::new_err(s.to_string()))
}

#[pyfunction]
fn count_batch<'py>(
    py: Python<'py>,
    spec: &Bound<'py, PyAny>,
    charts: &Bound<'py, PyAny>,
) -> PyResult<(usize, Vec<Vec<(i64, i64, i64)>>, Vec<(i64, i64)>)> {
    let (names, hua_table, bright, threads): (
        Vec<String>,
        HashMap<String, Vec<(String, String, String)>>,
        Vec<(String, String, String)>,
        Vec<Vec<(i64, String, String, bool, bool, Vec<(String, Vec<String>, bool)>)>>,
    ) = spec.extract()?;
    let charts: Vec<(String, String, i64, i64, i64)> = charts.extract()?;

    // slot table: 0..NPOS base, NPOS = 박사, then hua names
    let mut slot: HashMap<&str, usize> = HashMap::new();
    for (i, n) in POS_NAMES.iter().enumerate() { slot.insert(n, i); }
    slot.insert("박사", NPOS);
    let mut hnames: Vec<&str> = Vec::new();
    for rows in hua_table.values() {
        for (_, hn, _) in rows {
            if !hnames.contains(&hn.as_str()) { hnames.push(hn.as_str()); }
        }
    }
    for (k, hn) in hnames.iter().enumerate() { slot.insert(hn, NPOS + 1 + k); }
    let nslot = NPOS + 1 + hnames.len();
    if nslot > 128 { return Err(PyValueError::new_err("too many names")); }
    let mut in_names: u128 = 0;
    for n in &names { if let Some(s) = slot.get(n.as_str()) { in_names |= 1u128 << s; } }
    let mut main_mask: u128 = 0;
    for n in MAIN14.iter() { if let Some(s) = slot.get(n) { if in_names >> s & 1 == 1 { main_mask |= 1u128 << s; } } }

    // hua ids
    let mut hh_ids: Vec<&str> = Vec::new();
    for rows in hua_table.values() {
        for (hh, _, _) in rows { if !hh_ids.contains(&hh.as_str()) { hh_ids.push(hh.as_str()); } }
    }
    // per stem: Vec<(hh id, hua slot, star slot)>
    let mut hua_by_stem: [Option<Vec<(u8, usize, usize)>>; 10] = Default::default();
    for (stem, rows) in &hua_table {
        let si = match stem_idx(stem) { Ok(v) => v, Err(_) => continue };
        let mut v = Vec::new();
        for (hh, hn, star) in rows {
            let ss = match slot.get(star.as_str()) { Some(s) if *s <= NPOS => *s, _ => return key_err(star) };
            v.push((hh_ids.iter().position(|x| *x == hh.as_str()).unwrap() as u8, slot[hn.as_str()], ss));
        }
        hua_by_stem[si] = Some(v);
    }

    // brightness classes per (slot, branch): 0 missing, 1 묘왕, 2 함, 3 평, 4 other
    let mut bk = vec![[0u8; 12]; nslot];
    for (st, b, k) in &bright {
        let (Some(s), Some(bc)) = (slot.get(st.as_str()), one_char(b)) else { continue };
        let bi = match bi_c(bc) { Ok(v) => v as usize, Err(_) => continue };
        bk[*s][bi] = match k.as_str() { "묘왕" => 1, "함" => 2, "평" => 3, _ => 4 };
    }

    let mut trules: Vec<Vec<Rule>> = Vec::new();
    for rows in &threads {
        let mut rs = Vec::new();
        for (idx, star, br, is_hung, hung_only, toks) in rows {
            let mut tv = Vec::new();
            for (op, opts, flag) in toks {
                tv.push(match op.as_str() {
                    "身命" => Tok::ShenMing,
                    "命" => Tok::Ming,
                    "주성없음" => Tok::NoMain,
                    "궁" => {
                        let mut mk = 0u16;
                        for o in opts { if let Some(c) = one_char(o) { if let Ok(i) = bi_c(c) { mk |= 1 << i; } } }
                        Tok::Gung(mk)
                    }
                    "간" => {
                        let mut mk = 0u16;
                        for o in opts { if let Ok(i) = stem_idx(o) { mk |= 1 << i; } }
                        Tok::Gan(mk)
                    }
                    "화" => Tok::Hua(hh_ids.iter().position(|x| *x == opts[0].as_str()).map(|v| v as u8)),
                    "동궁" | "회" => {
                        let mut mk = 0u128;
                        let mut miss = false;
                        for o in opts {
                            match slot.get(o.as_str()) {
                                Some(s) if in_names >> s & 1 == 1 => mk |= 1u128 << s,
                                _ => miss = true,
                            }
                        }
                        if op == "동궁" { Tok::Dong(mk, *flag, miss) } else { Tok::Hoe(mk, *flag, miss) }
                    }
                    other => return key_err(other),
                });
            }
            rs.push(Rule {
                idx: *idx,
                star: slot.get(star.as_str()).copied(),
                br: match br.as_str() { "" => Br::None, "묘왕" => Br::MiaoWang, "함" => Br::Xian, "평" => Br::Ping, "비묘왕" => Br::NotMiaoWang, o => Br::Bad(o.to_string()) },
                is_hung: *is_hung,
                hung_only: *hung_only,
                toks: tv,
            });
        }
        trules.push(rs);
    }

    let nt = trules.len();
    let mut dist: Vec<Vec<(i64, i64, i64)>> = vec![Vec::new(); nt];
    let mut dindex: Vec<HashMap<(i64, i64), usize>> = vec![HashMap::new(); nt];
    let mut miss: Vec<(i64, i64)> = Vec::new();
    let mut mindex: HashMap<i64, usize> = HashMap::new();
    let mut n = 0usize;

    for (ys, yb, m, d, h) in &charts {
        let si = stem_idx(ys)?;
        let (base, ming, shen) = stars(ys, yb, *m, *d, *h)?;
        // slot values (branch index), -1 absent
        let mut val = [-1i8; 128];
        for i in 0..NPOS { val[i] = base[i].rem_euclid(12) as i8; }
        val[NPOS] = val[slot["녹존"]];
        let mut hua_of = [255u8; 128];
        let rows = match &hua_by_stem[si] { Some(r) => r, None => return key_err(ys) };
        for (hid, hs, ss) in rows {
            val[*hs] = val[*ss];
            hua_of[*ss] = *hid;
        }
        let mut at = [0u128; 12];
        let mut bits = in_names;
        while bits != 0 {
            let s = bits.trailing_zeros() as usize;
            bits &= bits - 1;
            if s < nslot && val[s] >= 0 { at[val[s] as usize] |= 1u128 << s; }
        }
        let ming = ming as usize;
        let shen = shen as usize;
        let mut zone = [0u8; 12];
        zone[ming] = 1;
        zone[shen] = 1;
        for z in [ming, (ming + 6) % 12, (ming + 8) % 12, (ming + 4) % 12] {
            if zone[z] == 0 { zone[z] = 2; }
        }

        for (t, rs) in trules.iter().enumerate() {
            let (mut dong, mut sam, mut hung, mut ms) = (0i64, 0i64, 0i64, 0i64);
            for r in rs {
                let Some(s) = r.star else { continue };
                if val[s] < 0 { continue; }
                let z = val[s] as usize;
                let zn = zone[z];
                if zn == 0 { continue; }
                let mut ok = true;
                for tk in &r.toks {
                    let hold = match tk {
                        Tok::ShenMing => z == ming || z == shen,
                        Tok::Ming => z == ming,
                        Tok::NoMain => at[z] & main_mask == 0,
                        Tok::Gung(mk) => mk >> z & 1 == 1,
                        Tok::Gan(mk) => mk >> si & 1 == 1,
                        Tok::Hua(v) => match v { Some(id) => hua_of[s] == *id, None => false },
                        Tok::Dong(mk, allm, miss) | Tok::Hoe(mk, allm, miss) => {
                            let have = if matches!(tk, Tok::Dong(..)) {
                                at[z]
                            } else {
                                at[z] | at[(z + 6) % 12] | at[(z + 8) % 12] | at[(z + 4) % 12]
                            } & !(1u128 << s);
                            if *allm { !*miss && have & mk == *mk } else { have & mk != 0 }
                        }
                    };
                    if !hold { ok = false; break; }
                }
                if !ok { continue; }
                match &r.br {
                    Br::None => {}
                    br => {
                        let k = bk[s][z];
                        if k == 0 {
                            ms += 1;
                            let e = *mindex.entry(r.idx).or_insert_with(|| { miss.push((r.idx, 0)); miss.len() - 1 });
                            miss[e].1 += 1;
                            continue;
                        }
                        let pass = match br {
                            Br::MiaoWang => k == 1,
                            Br::Xian => k == 2,
                            Br::Ping => k == 3,
                            Br::NotMiaoWang => k != 1,
                            Br::Bad(o) => return key_err(o),
                            Br::None => true,
                        };
                        if !pass { continue; }
                    }
                }
                if r.hung_only { hung += 1; continue; }
                if zn == 1 { dong += 1 } else { sam += 1 }
                if r.is_hung { hung += 1; }
            }
            let _ = (hung, ms);
            let e = *dindex[t].entry((dong, sam)).or_insert_with(|| { dist[t].push((dong, sam, 0)); dist[t].len() - 1 });
            dist[t][e].2 += 1;
        }
        n += 1;
    }
    let _ = py;
    Ok((n, dist, miss))
}

#[pymodule]
fn fa_engine_v2_popcore_count_batch(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(count_batch, m)?)?;
    Ok(())
}
